using System.Collections.Generic;
using HelixPythonNamespace.GuiDesigner.Emit;
using HelixPythonNamespace.GuiDesigner.Model;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using K = HelixPythonNamespace.GuiDesigner.Model.GuiControlKind;

namespace HelixPythonNamespace.GuiDesigner.Tests
{
    /// <summary>
    /// <c># region UserCode</c> round-trip: the one promise the designer makes about a file it
    /// otherwise rewrites in full.
    ///
    /// <para>
    /// The bug these pin destroyed user code silently. The generated banner reads
    /// <c># AUTO-GENERATED by HelixPython. Edit only inside `# region UserCode-*` blocks.</c> — and
    /// the parser's pattern was not anchored to the start of a line, so the BANNER matched as a
    /// region opener. Its lazy body then ran to the first real <c># endregion</c>, swallowing the
    /// whole of the first handler's region; the regeneration found no entry for that handler and
    /// wrote the default <c>pass</c> over whatever the user had written there. Nothing failed and
    /// nothing was reported: the file still compiled, and one button had quietly stopped working.
    /// </para>
    /// </summary>
    [TestClass]
    public class CodeRegionPreserverBannerTests
    {
        private const string Banner =
            "# AUTO-GENERATED by HelixPython. Edit only inside `# region UserCode-*` blocks.\n";

        [TestMethod]
        public void TheBannerIsNotARegionOpener()
        {
            string source =
                Banner +
                "import tkinter as tk\n" +
                "\n" +
                "    # region UserCode-first\n" +
                "    def first(self):\n" +
                "        return 'kept'\n" +
                "    # endregion\n" +
                "\n" +
                "    # region UserCode-second\n" +
                "    def second(self):\n" +
                "        return 'also kept'\n" +
                "    # endregion\n";

            Dictionary<string, string> regions = CodeRegionPreserver.Parse(source);

            Assert.IsTrue(regions.ContainsKey("UserCode-first"),
                "the first region was swallowed by the banner");
            Assert.IsTrue(regions.ContainsKey("UserCode-second"));
            StringAssert.Contains(regions["UserCode-first"], "return 'kept'");
            StringAssert.Contains(regions["UserCode-second"], "return 'also kept'");
            Assert.AreEqual(2, regions.Count,
                "the banner must not contribute a region of its own: " + string.Join(", ", regions.Keys));
        }

        [TestMethod]
        public void ARegionMarkerInsideALineIsNotAMarker()
        {
            // Same rule, stated generally: a comment or a docstring that mentions the syntax is
            // prose, not structure.
            string source =
                "# see `# region Foo` for details\n" +
                "    # region UserCode-real\n" +
                "    body\n" +
                "    # endregion\n";
            Dictionary<string, string> regions = CodeRegionPreserver.Parse(source);
            CollectionAssert.AreEqual(new[] { "UserCode-real" }, new List<string>(regions.Keys));
        }

        /// <summary>
        /// The end-to-end version: emit, edit every region, emit again, and get the edits back.
        /// The parser test above would have passed at any point with a lenient enough regex; this
        /// one fails if the two halves ever stop agreeing on what a region is.
        /// </summary>
        [TestMethod]
        public void EveryEditedRegion_SurvivesARegeneration()
        {
            var form = new GuiForm { FormClassName = "RoundTripForm", Title = "Round trip" };
            string[] handlers = { "on_first", "on_second", "on_third" };
            for (int i = 0; i < handlers.Length; i++)
            {
                var button = new GuiControl
                {
                    Id = "b" + i, Kind = K.Button, Name = "btn" + i, X = 10, Y = 10 + i * 30,
                };
                button.Events.Add(new GuiEvent { EventName = "command", HandlerName = handlers[i] });
                form.Controls.Add(button);
            }

            var emitter = new TkinterEmitter();
            string first = emitter.Emit(form, string.Empty);

            // Stand in for the user typing in each region.
            string edited = first;
            foreach (string handler in handlers)
                edited = edited.Replace(
                    "    def " + handler + "(self):\n        pass\n",
                    "    def " + handler + "(self):\n        return '" + handler + " body'\n");
            edited = edited.Replace(
                "if __name__ == '__main__':\n    root = tk.Tk()",
                "if __name__ == '__main__':\n    print('main body')\n    root = tk.Tk()");

            string second = emitter.Emit(form, edited);

            foreach (string handler in handlers)
                StringAssert.Contains(second, "return '" + handler + " body'",
                    handler + "'s region was lost on regeneration");
            StringAssert.Contains(second, "print('main body')", "the main region was lost");
        }
    }
}
